import de.maxhenkel.voicechat.VoicechatClient;
import de.maxhenkel.voicechat.voice.client.SoundManager;
import de.maxhenkel.voicechat.voice.client.speaker.ALSpeaker;
import de.maxhenkel.voicechat.voice.client.speaker.ALSpeakerBase;
import de.maxhenkel.voicechat.voice.client.speaker.AudioType;
import de.maxhenkel.voicechat.voice.client.speaker.FakeALSpeaker;
import de.maxhenkel.voicechat.voice.client.speaker.MonoALSpeaker;
import de.maxhenkel.voicechat.voice.client.speaker.Speaker;
import de.maxhenkel.voicechat.voice.client.speaker.SpeakerException;
import java.util.UUID;
import javax.annotation.Nullable;

public class SpeakerManager {
    public static Speaker createSpeaker(SoundManager soundManager, @Nullable UUID audioChannel) throws SpeakerException {
        ALSpeakerBase speaker = switch (VoicechatClient.CLIENT_CONFIG.audioType.get()) {
            default -> throw new IncompatibleClassChangeError();
            case AudioType.NORMAL -> new ALSpeaker(soundManager, 48000, 960, audioChannel);
            case AudioType.REDUCED -> new FakeALSpeaker(soundManager, 48000, 960, audioChannel);
            case AudioType.OFF -> new MonoALSpeaker(soundManager, 48000, 960, audioChannel);
        };
        try {
            soundManager.trackSpeaker(speaker);
            speaker.open();
        }
        catch (Throwable t) {
            speaker.close();
            throw t;
        }
        return speaker;
    }
}

